-- Generated by Claude Code — Kennzahlen für den täglichen Datenqualitäts-
-- Bericht (Mail an die Redaktion, admin /api/cron/daily).
create or replace function public.data_quality_report()
returns jsonb
language sql
security definer
set search_path = public
stable
as $$
  with upcoming as (
    select e.id, e.source_id, e.image_urls, e.ticket_url, e.website_url
    from events e
    where e.status = 'scheduled' and e.start_datetime >= now()
  ),
  per_source as (
    select
      coalesce(s.name, 'Manuell / ohne Quelle') as source,
      count(*) as events,
      count(*) filter (where coalesce(array_length(u.image_urls, 1), 0) = 0
        and not exists (select 1 from images i where i.origin_type = 'event' and i.origin_id = u.id)) as without_image,
      count(*) filter (where u.ticket_url is null and u.website_url is null) as without_link,
      count(*) filter (where not exists (select 1 from event_participants p where p.event_id = u.id)) as without_participants,
      count(*) filter (where not exists (select 1 from event_works w where w.event_id = u.id)) as without_program
    from upcoming u
    left join sources s on s.id = u.source_id
    group by 1
  )
  select jsonb_build_object(
    'generated_at', now(),
    'upcoming_events', (select count(*) from upcoming),
    'sources', (select coalesce(jsonb_agg(to_jsonb(p) order by p.events desc), '[]'::jsonb) from per_source p),
    'stale_sources', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'last_run_at', last_run_at) order by last_run_at nulls first), '[]'::jsonb)
      from sources where status = 'active' and (last_run_at is null or last_run_at < now() - interval '2 days')
    ),
    'pending_person_duplicates', (select count(*) from person_duplicate_candidates where status = 'pending'),
    'pending_entity_candidates', (select count(*) from entity_candidates where status = 'pending'),
    'pending_claims', (select count(*) from entity_claims where status = 'pending'),
    'persons_without_photo', (select count(*) from persons where photo_url is null
      and not exists (select 1 from images i where i.origin_type = 'person' and i.origin_id = persons.id))
  );
$$;

revoke all on function public.data_quality_report() from public, anon, authenticated;
grant execute on function public.data_quality_report() to service_role;
